function 子用户管理_渲染表格(users) {
    const tbody = document.getElementById('子用户管理_TableBody');
    
    tbody.innerHTML = '';
    
    if (users.length === 0) {
        const emptyRow = document.createElement('tr');
        emptyRow.innerHTML = `
            <td colspan="11" style="text-align: center; padding: 15vh; color: #666;">
                <i class="fas fa-ban" style="font-size: 48px; margin-bottom: 16px; display: block; opacity: 0.3;"></i>
                <div style="font-size: 14px;">暂无子用户</div>
            </td>
        `;
        tbody.appendChild(emptyRow);
        return;
    }
    
    users.forEach((user, index) => {
        const row = document.createElement('tr');
        const isChecked = 子用户管理_选中的.has(user.用户UID);
        
        const announcementSafe = user.announcement ? 
            user.announcement
                .replace(/\\/g, '\\\\')
                .replace(/'/g, "\\'")
                .replace(/"/g, '\\"')
                .replace(/\n/g, '\\n')
                .replace(/\r/g, '\\r') : '';
        
        let unbanTimeText = '';
        let statusBadge = '';
        
        const currentTime = Date.now();
        const banTimestamp = parseInt(user['封禁状态']);
        const lastLoginTime  = (user['上次登陆时间']);
        const isBanned = banTimestamp > 0 && banTimestamp > currentTime;
        
        // ✅ 直接使用PHP返回的 is_online 字段
        const isOnline = user.is_online || false;
        
        // ✅ 在线状态显示
        let onlineBadge = '';
        if (isOnline) {
            onlineBadge = `<span style="color: #00cc00;"><i class="fas fa-circle" style="font-size: 10px;"></i> 在线</span>`;
        } else {
            onlineBadge = `<span style="color: #999;"><i class="far fa-circle" style="font-size: 10px;"></i> 离线</span>`;
        }

        if (isBanned) {
            const remainingMs = banTimestamp - currentTime;
            
            const days = Math.floor(remainingMs / (1000 * 60 * 60 * 24));
            const hours = Math.floor((remainingMs % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
            const minutes = Math.floor((remainingMs % (1000 * 60 * 60)) / (1000 * 60));

            const unbanDate = new Date(banTimestamp);
            const unbanTime = unbanDate.toLocaleString('zh-CN', {
                year: 'numeric',
                month: '2-digit',
                day: '2-digit',
                hour: '2-digit',
                minute: '2-digit'
            }).replace(/\//g, '-');
            
            statusBadge = `
                <span style="color :#f10000;">
                    <i></i> 封禁中
                </span>
            `;
            
            unbanTimeText = `
                <span style="color :#f10000;">
                    <i></i> ${unbanTime}
                </span>
            `;
        } else if (banTimestamp > 0 && banTimestamp <= currentTime) {
            statusBadge = `
                <span>
                    <i></i> 已解封
                </span>
            `;
            
            unbanTimeText = `
                <span>
                    <i></i> 已解封
                </span>
            `;
        } else {
            statusBadge = `
                <span>
                    <i></i> 正常
                </span>
            `;
            
            unbanTimeText = `
                <span>
                    <i></i> 正常
                </span>
            `;
        }
        
        const ipLocation = user['I位置'] || '';
        const realIp = user['IP'] || user['ip'] || '';
        const createTime = user['创建时间'];
        const 流量使用 = (parseInt(user['使用的流量_次数'], 10) || 0) + ' 次';
        
        row.innerHTML = `
            <td>
                <input type="checkbox" class="子用户管理-选择按钮" value="${user.用户UID}" ${isChecked ? 'checked' : ''} 
                       onchange="子用户管理_选择按钮处理事件('${user.用户UID}', this.checked)">
            </td>

            <td>
                <span>
                    ${user.用户UID}
                </span>
            </td>
            
            <td>
                ${onlineBadge}
            </td>
            
            <td>
                <span>
                    ${user.游戏UID && user.游戏UID !== '无' ? escapeHtml(user.游戏UID) : '<span style="color:#bbb;">无</span>'}
                </span>
            </td>
            <td>
                <span>
                    ${user.游戏昵称 && user.游戏昵称 !== '无' ? escapeHtml(user.游戏昵称) : '<span style="color:#bbb;">无</span>'}
                </span>
            </td>

            <td>
                ${statusBadge}
            </td>
            
            <td>
                ${unbanTimeText}
            </td>

            <td>
                ${流量使用}
            </td>
            
            <td>
                ${lastLoginTime}
            </td>
                    
            <td>
                ${ipLocation ? escapeHtml(ipLocation) : '<span style=\"color:#bbb;\">未知</span>'}
                ${realIp ? `<br><span style=\"font-size:11px;color:#999;\">${escapeHtml(realIp)}</span>` : ''}
            </td>
                    
            <td>
                ${createTime}
            </td>
                    
            <td style="text-align: center;">
                <div class="btn-group-compact">
                    <button class="按钮" onclick="viewIpInfo('${escapeHtml(realIp)}')" title="查看IP信息"${realIp ? '' : ' disabled style="opacity:.45;cursor:not-allowed;"'}>
                        <i class="fas fa-map-marker-alt"></i> IP信息
                    </button>
                    <button class="按钮" onclick="查询绑定('${user.用户UID}')" title="查询绑定">
                        <i class="fas fa-key"></i> 查询绑定
                    </button>
                    <button class="按钮" onclick="openBanUserModal('${user.用户UID}', ${isBanned})" title="封禁/解封">
                        <i class="fas ${isBanned ? 'fa-unlock' : 'fa-ban'}"></i> ${isBanned ? '解封用户' : '封禁用户'}
                    </button>
                    <button class="按钮" onclick="deleteUser('${user.用户UID}')" title="删除用户">
                        <i class="fas fa-trash"></i> 删除用户
                    </button>
                </div>
            </td>
        `;
        tbody.appendChild(row);
    });
}


