function formatRemainingTime(timestamp) {
    if (timestamp <= 0) return { text: '已解封', isExpired: true };
    
    const currentTime = Date.now();
    if (timestamp <= currentTime) return { text: '已到期', isExpired: true };
    
    const remainingMs = timestamp - currentTime;
    const days = Math.floor(remainingMs / (1000 * 60 * 60 * 24));
    const hours = Math.floor((remainingMs % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    const minutes = Math.floor((remainingMs % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((remainingMs % (1000 * 60)) / 1000);
    
    let text = '剩余';
    if (days > 0) text += `${days}天`;
    if (hours > 0) text += `${hours}小时`;
    if (minutes > 0 && days === 0) text += `${minutes}分`;
    if (seconds > 0 && days === 0 && hours === 0) text += `${seconds}秒`;
    
    // 格式化解封时间
    const unbanDate = new Date(timestamp);
    const unbanTime = unbanDate.toLocaleString('zh-CN', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    }).replace(/\//g, '-');
    
    return {
        text: text || '即将解封',
        unbanTime: unbanTime,
        timestamp: timestamp,
        remainingMs: remainingMs,
        isExpired: false
    };
}
