async function confirmBanUser(userId, isCurrentlyBanned) {
    const modal = document.getElementById('banUserModal');
    
    try {
        if (isCurrentlyBanned) {
            // 解封操作
            const params = {
                action: 'change_ban_status',
                password: 开发者安全密码,
                user_uid: userId,
                add_hours: 0,
                add_days: 0
            };
            
            const result = await POSTUSERPHP(params, 当前选中的应用ID);
            
            if (result.success) {
                alert('用户解封成功', 'success');
                // 重新加载用户列表
                加载子用户数据(子用户管理_当前页码);
                closeBanUserModal();
            } else {
                alert('解封失败: ' + result.message, 'error');
            }
        } else {
            // 封禁操作
            const daysInput = document.getElementById('banDaysInput');
            const hoursInput = document.getElementById('banHoursInput');
            
            const addDays = parseInt(daysInput?.value || 0);
            const addHours = parseInt(hoursInput?.value || 0);
            
            if (addDays === 0 && addHours === 0) {
                alert('请至少设置一个非零的封禁时长', 'warning');
                return;
            }
            
            const params = {
                action: 'change_ban_status',
                password: 开发者安全密码,
                user_uid: userId,
                add_hours: addHours,
                add_days: addDays
            };
            
            const result = await POSTUSERPHP(params, 当前选中的应用ID);
            
            if (result.success) {
                alert('用户封禁成功', 'success');
                // 重新加载用户列表
                加载子用户数据(子用户管理_当前页码);
                closeBanUserModal();
            } else {
                alert('封禁失败: ' + result.message, 'error');
            }
        }
    } catch (error) {
        alert('操作失败: ' + error.message, 'error');
    }
}






function closeBanUserModal() {
    const modal = document.getElementById('banUserModal');
    if (modal) {
        modal.style.display = 'none';
        document.body.style.overflow = 'auto';
    }
}

