function formatDateTime(timestamp) {
    if (!timestamp) return '';
    
    // 如果已经是格式化好的时间字符串，直接返回
    if (typeof timestamp === 'string' && timestamp.includes('-')) {
        return timestamp;
    }
    
    // 如果是时间戳，进行转换
    try {
        const date = new Date(parseInt(timestamp));
        if (isNaN(date.getTime())) return timestamp;
        
        return date.toLocaleString('zh-CN', {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit'
        }).replace(/\//g, '-');
    } catch (e) {
        return timestamp;
    }
}

// 修改 updateUserStats 函数
function updateUserStats(data) {
    const totalUsers = document.getElementById('totalUsers');
    const normalUsers = document.getElementById('normalUsers');
    const bannedUsers = document.getElementById('bannedUsers');
    
    if (!totalUsers || !normalUsers || !bannedUsers) return;
    
    // 判断传入的是 stats 对象还是 users 数组
    if (data && typeof data === 'object') {
        // 如果传入的是 stats 对象
        if (data.total !== undefined && data.normal !== undefined && data.banned !== undefined) {
            totalUsers.textContent = data.total || 0;
            normalUsers.textContent = data.normal || 0;
            bannedUsers.textContent = data.banned || 0;
            return;
        }
        
        // 如果传入的是 users 数组
        if (Array.isArray(data)) {
            const currentTime = Date.now();
            let bannedCount = 0;
            
            data.forEach(user => {
                const banTimestamp = parseInt(user['封禁状态']) || 0;
                if (banTimestamp > 0 && banTimestamp > currentTime) {
                    bannedCount++;
                }
            });
            
            const total = data.length;
            const normal = total - bannedCount;
            
            totalUsers.textContent = total;
            normalUsers.textContent = normal;
            bannedUsers.textContent = bannedCount;
            return;
        }
    }
    
    // 默认值
    totalUsers.textContent = 0;
    normalUsers.textContent = 0;
    bannedUsers.textContent = 0;
}
